fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Precondition: list.len() > 0 and 0 < n < list.len()
    let len = list.len();
    let mut new_list = Vec::with_capacity(len);

    // First take the subarray from n (inclusive) to the end
    new_list.extend_from_slice(&list[n..]);

    // Then take the subarray from 0 (inclusive) to n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}

